import uuid
from datetime import date
from decimal import Decimal

from sqlalchemy.orm import Session

from src.backend.db.repositories.audit_repo import create_entry
from src.backend.db.repositories.project_repo import (
    create as create_project,
    get_by_id as get_project_by_id,
    list_projects,
    soft_delete as soft_delete_project,
    update as update_project,
)
from src.backend.models.project import Project
from src.backend.schemas.project import ProjectCreate, ProjectUpdate


def _get_names(db: Session, project: Project) -> dict:
    client = db.query(Project).filter_by(id=project.id).first()
    names = {
        "client_name": None,
        "pm_name": None,
        "designer_name": None,
        "auditor_name": None,
    }
    if project.client_id:
        from src.backend.models.client import Client

        c = db.query(Client).filter(Client.id == project.client_id).first()
        if c:
            names["client_name"] = c.name
    if project.pm_id:
        from src.backend.models.user import User

        u = db.query(User).filter(User.id == project.pm_id).first()
        if u:
            names["pm_name"] = u.name
    if project.designer_id:
        from src.backend.models.user import User

        u = db.query(User).filter(User.id == project.designer_id).first()
        if u:
            names["designer_name"] = u.name
    if project.auditor_id:
        from src.backend.models.user import User

        u = db.query(User).filter(User.id == project.auditor_id).first()
        if u:
            names["auditor_name"] = u.name
    return names


def list_projects_service(
    db: Session,
    page: int = 1,
    page_size: int = 20,
    q: str | None = None,
    status: str | None = None,
) -> tuple[list[Project], int, int, int]:
    items, total = list_projects(db, page, page_size, q, status)
    return items, total, page, page_size


def create_project_service(
    db: Session,
    data: ProjectCreate,
    actor_id: uuid.UUID | None,
) -> Project:
    project = create_project(
        db,
        client_id=data.client_id,
        name=data.name,
        code=data.code,
        status=data.status.value if data.status else "Lead",
        description=data.description,
        pm_id=data.pm_id,
        designer_id=data.designer_id,
        auditor_id=data.auditor_id,
        location=data.location,
        estimated_value=data.estimated_value,
        start_date=data.start_date,
        target_end_date=data.target_end_date,
    )

    create_entry(
        db,
        action="project.create",
        entity_type="project",
        entity_id=project.id,
        user_id=actor_id,
        after_json={
            "id": str(project.id),
            "name": project.name,
            "code": project.code,
            "status": project.status,
        },
    )

    return project


def get_project_service(db: Session, project_id: uuid.UUID) -> Project | None:
    return get_project_by_id(db, project_id)


def update_project_service(
    db: Session,
    project_id: uuid.UUID,
    data: ProjectUpdate,
    actor_id: uuid.UUID | None,
) -> Project | None:
    project = get_project_by_id(db, project_id)
    if not project:
        return None

    before_json = {
        "name": project.name,
        "code": project.code,
        "status": project.status,
    }

    if data.name is not None:
        project.name = data.name
    if data.code is not None:
        project.code = data.code
    if data.description is not None:
        project.description = data.description
    if data.status is not None:
        project.status = data.status.value
    if data.pm_id is not None:
        project.pm_id = data.pm_id
    if data.designer_id is not None:
        project.designer_id = data.designer_id
    if data.auditor_id is not None:
        project.auditor_id = data.auditor_id
    if data.location is not None:
        project.location = data.location
    if data.estimated_value is not None:
        project.estimated_value = data.estimated_value
    if data.actual_value is not None:
        project.actual_value = data.actual_value
    if data.start_date is not None:
        project.start_date = data.start_date
    if data.target_end_date is not None:
        project.target_end_date = data.target_end_date
    if data.actual_end_date is not None:
        project.actual_end_date = data.actual_end_date
    if data.is_active is not None:
        project.is_active = data.is_active

    update_project(db, project)

    after_json = {
        "name": project.name,
        "code": project.code,
        "status": project.status,
    }

    create_entry(
        db,
        action="project.update",
        entity_type="project",
        entity_id=project.id,
        user_id=actor_id,
        before_json=before_json,
        after_json=after_json,
    )

    return project


def soft_delete_project_service(
    db: Session,
    project_id: uuid.UUID,
    actor_id: uuid.UUID | None,
) -> bool:
    project = get_project_by_id(db, project_id)
    if not project:
        return False

    before_json = {"deleted_at": None}

    soft_delete_project(db, project)

    after_json = {"deleted_at": str(project.deleted_at)}

    create_entry(
        db,
        action="project.delete",
        entity_type="project",
        entity_id=project.id,
        user_id=actor_id,
        before_json=before_json,
        after_json=after_json,
    )

    return True

