     update_draft_quote,
 )

 router = APIRouter(prefix="/api", tags=["quotes"])


 def _get_quote(db: Session, quote_id: uuid.UUID):
     quote = get_by_id(db, quote_id)
     if not quote:
         raise HTTPException(status_code=404, detail="Quote not found")
     return quote


 def _quote_dict_with_names(db: Session, quote) -> dict:
     from src.backend.services.quote_service import _quote_to_dict
     # Eager load relationships if not already loaded
     if hasattr(quote, "project") and quote.project:
         _ = quote.project.name
         if hasattr(quote.project, "client") and quote.project.client:
             _ = quote.project.client.name
     if hasattr(quote, "creator") and quote.creator:
         _ = quote.creator.name
     if hasattr(quote, "approver") and quote.approver:
         _ = quote.approver.name
     return _quote_to_dict(quote)


 @router.post("/projects/{project_id}/quotes", status_code=status.HTTP_201_CREATED)
 def create_quote(
     project_id: uuid.UUID,
