         return QuoteRead.model_validate(result)
     except ValueError as e:
         raise HTTPException(status_code=400, detail=str(e))


 @router.post("/quotes/{quote_id}/respond", response_model=QuoteRead)
 def respond_quote(
     quote_id: uuid.UUID,
