+  <script>
+    const slides = document.querySelectorAll('.slide');
+    let current = 0;
+
+    function showSlide(i) {
+      slides.forEach((s, idx) => {
+        s.classList.remove('active', 'prev');
+        if (idx === i) s.classList.add('active');
+        else if (idx < i) s.classList.add('prev');
+      });
+      document.getElementById('progress').style.width = ((i + 1) / slides.length * 100) + '%';
+    }
+
+    function next() {
+      if (current < slides.length - 1) { current++; showSlide(current); }
+    }
+    function prev() {
+      if (current > 0) { current--; showSlide(current); }
+    }
+
+    document.addEventListener('keydown', (e) => {
+      if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'ArrowDown') {
+        e.preventDefault(); next();
+      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
+        e.preventDefault(); prev();
+      }
+    });
+
+    document.addEventListener('click', (e) => {
+      const mid = window.innerWidth / 2;
+      if (e.clientX > mid) next(); else prev();
+    });
+
+    showSlide(0);
+  </script>
